package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamTensesBank1 {
  private const val T = "Tenses: Present & Future Forms"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("Water ___ at 100 degrees Celsius under normal atmospheric pressure.", "boils", "is boiling", "boiled", "will boiling", "Scientific facts always use the Simple Present tense."),
    q("My father ___ the morning newspaper before leaving for work.", "reads", "readed", "is reading", "reading", "Daily habits take Simple Present; singular 'father' takes '-s'."),
    q("The express train to Badulla ___ Colombo Fort at 5:55 a.m. daily.", "departs", "is depart", "departed", "will departed", "Fixed timetables use Simple Present tense."),
    q("Bees ___ nectar from colourful garden blossoms to make honey.", "collect", "collects", "collected", "are collect", "General truths with plural subject 'bees' take base verb 'collect'."),
    q("Does Kasun ___ to the library every Saturday afternoon?", "go", "goes", "went", "going", "After auxiliary 'Does', the main verb takes its base form 'go'."),
    q("Nimali ___ not like overly spicy food at lunch.", "does", "do", "is", "has", "Third-person singular negative in Simple Present uses 'does not'."),
    q("We ___ usually watch television on weekday evenings.", "do", "does", "are", "were", "Plural subject 'we' with base verb 'watch' uses 'do'."),
    q("Listen! Someone ___ the flute in the music room right now.", "is playing", "plays", "played", "has play", "'Listen!' signals an action happening now -> Present Continuous."),
    q("Look at the dark clouds; it ___ to rain heavily.", "is starting", "starts", "started", "was start", "'Look!' directs attention to a present unfolding action."),
    q("At the moment, the Grade 11 students ___ for their term test.", "are revising", "revise", "revised", "were revising", "'At the moment' requires Present Continuous ('are revising')."),
    q("Don't disturb Mala now; she ___ an important formal letter.", "is writing", "writes", "wrote", "has write", "An activity occurring right now uses Present Continuous."),
    q("Why ___ you wearing a heavy coat in this warm weather?", "are", "do", "have", "were", "Present Continuous question structure uses 'are + subject + V-ing'."),
    q("I ___ the correct answer to that riddle already.", "know", "am knowing", "knowing", "have knew", "'Know' is a stative verb and is not used in continuous tenses."),
    q("This old wooden box ___ to my grandfather.", "belongs", "is belonging", "belonging", "has belong", "'Belong' is a stative verb expressing possession."),
    q("She ___ what the science teacher explained this morning.", "understands", "is understanding", "understanding", "understand", "'Understand' is a mental stative verb taking Simple Present."),
    q("The fresh jasmine flowers ___ wonderful in the morning.", "smell", "are smelling", "smelling", "smells", "Plural 'flowers' + stative verb 'smell' takes base form."),
    q("Tharindu ___ just finished painting the scenery for the play.", "has", "is", "was", "did", "'Just + past participle' forms Present Perfect with 'has'."),
    q("We ___ already submitted our science project reports.", "have", "are", "were", "did", "'Have already + V3' expresses a recently completed action."),
    q("Have you ever ___ Sigiriya Rock Fortress during a school trip?", "climbed", "climb", "climbing", "climbs", "Life experiences use 'Have you ever + V3 (climbed)'."),
    q("I haven't ___ my lost geometry box anywhere yet.", "found", "find", "finding", "finds", "Present Perfect negative requires the past participle 'found'."),
    q("The postman ___ brought any letters for us today.", "hasn't", "didn't", "isn't", "wasn't", "With past participle 'brought' and 'today', use 'hasn't'."),
    q("Mrs. Wijesinghe ___ taught English at this school since 2014.", "has", "is", "did", "was", "'Since 2014' with past participle 'taught' takes 'has'."),
    q("They ___ lived in Kandy for nearly twelve years.", "have", "are", "were", "did", "'For twelve years' continuing to the present takes 'have lived'."),
    q("Look! The stray dog ___ fallen into the muddy ditch.", "has", "is", "was", "did", "A past event with a visible present result uses 'has fallen'."),
    q("Where is Ruwan? He has ___ to the bookshop to buy pens.", "gone", "been", "went", "going", "'Has gone to' means he is still away there now."),
    q("My aunt has ___ to Galle twice this month and is back home.", "been", "gone", "went", "going", "'Has been to' means she visited and returned."),
    q("It has ___ raining steadily since seven o'clock this morning.", "been", "being", "be", "was", "Present Perfect Continuous uses 'has been + V-ing'."),
    q("How long ___ you been waiting at the railway station?", "have", "are", "did", "were", "Duration up to now takes 'have you been waiting'."),
    q("The gardeners ___ been trimming the hedges all afternoon.", "have", "are", "were", "was", "Plural 'gardeners' + 'been trimming' requires 'have'."),
    q("He ___ been practising the violin for two hours without a break.", "has", "is", "was", "had", "Ongoing action up to now with singular 'He' takes 'has'."),
    q("By next Friday, the painters ___ finish decorating the hall.", "will", "did", "have", "were", "Simple Future for a future time uses 'will + base verb'."),
    q("Don't worry about the heavy trunk; I ___ help you carry it.", "will", "am", "was", "did", "Spontaneous offers of help take 'will + base verb'."),
    q("Look at those dark clouds! It ___ to pour any minute now.", "is going", "will going", "goes", "has gone", "Present evidence pointing to an imminent event uses 'is going to'."),
    q("We ___ visit our grandparents in Matara next weekend.", "are going to", "will going to", "went to", "have gone", "A pre-decided future plan uses 'are going to + V1'."),
    q("This time tomorrow, we ___ flying over the Bay of Bengal.", "will be", "will have", "are been", "were", "Action in progress at a specific future moment takes 'will be + V-ing'."),
    q("At 8:00 p.m. tonight, the orchestra ___ performing on stage.", "will be", "will been", "is been", "has been", "Future Continuous 'will be + V-ing' fits a fixed future time."),
    q("By the end of December, they ___ completed the new library.", "will have", "will be", "are having", "have had", "'By + future time' takes Future Perfect 'will have + V3'."),
    q("By 2030, solar energy ___ replaced many older power stations.", "will have", "will be", "will having", "is having", "Completed action before a future deadline takes 'will have + V3'."),
    q("When you arrive at the station, I ___ waiting near the exit.", "will be", "will been", "am been", "was", "Future Continuous describes an ongoing background action when another arrives."),
    q("As soon as the bell ___, the students will assemble in the hall.", "rings", "will ring", "rang", "ringing", "Time clauses with 'as soon as' use Simple Present for future meaning."),
    q("Wait here until the heavy rain ___ completely.", "stops", "will stop", "stopped", "stopping", "After 'until' referring to future time, use Simple Present."),
    q("Before she ___ for the interview, she will check all certificates.", "leaves", "will leave", "left", "leaving", "Future time clause with 'before' uses Simple Present 'leaves'."),
    q("Please call me when you ___ safely in Kurunegala.", "arrive", "will arrive", "arrived", "arriving", "'When' clause with future main verb uses Simple Present 'arrive'."),
    q("After the meeting ___, we shall distribute the refreshments.", "ends", "will end", "ended", "ending", "'After' clause referring to the future takes Simple Present."),
    q("Every morning, the bakery ___ fresh loaves of bread at six.", "bakes", "bake", "is baking", "baked", "Singular subject 'the bakery' + routine takes 'bakes'."),
    q("Birds of a feather ___ together, as the old proverb says.", "flock", "flocks", "flocked", "are flocking", "Proverbs use Simple Present; plural 'birds' takes 'flock'."),
    q("Our school term ___ on Monday next week according to the circular.", "begins", "is begin", "began", "was beginning", "Scheduled calendar events use Simple Present 'begins'."),
    q("Why does your sister ___ so early on Sunday mornings?", "wake up", "wakes up", "woke up", "waking up", "'Does + subject' always pairs with the base verb 'wake up'."),
    q("The Earth ___ around the Sun once every 365 days.", "revolves", "revolve", "is revolving", "revolved", "Astronomical facts take Simple Present singular 'revolves'."),
    q("Currently, many schools ___ digital smartboards in classrooms.", "are installing", "install", "installed", "were install", "'Currently' signals a developing present trend -> Present Continuous."),
    q("More and more teenagers ___ learning coding after school.", "are", "do", "have", "was", "Gradual present changes use 'are + V-ing' ('are learning')."),
    q("Be quiet! The baby ___ peacefully in the cradle.", "is sleeping", "sleeps", "slept", "has sleep", "'Be quiet!' indicates an ongoing present action -> 'is sleeping'."),
    q("She ___ currently working on an essay about wildlife conservation.", "is", "does", "has", "was", "Present Continuous requires 'is' before 'working'."),
    q("I ___ my umbrella at home, so I am getting wet now.", "have left", "leave", "am leaving", "had leave", "Past action causing a present situation takes Present Perfect."),
    q("We ___ seen this informative wildlife film twice already.", "have", "are", "were", "did", "Experience up to the present takes 'have seen'."),
    q("Has Kamal ___ the invitation cards to the chief guest yet?", "sent", "send", "sending", "sends", "Question in Present Perfect uses 'Has + subject + V3 (sent)'."),
    q("She hasn't spoken to her cousin ___ last April.", "since", "for", "from", "during", "Point in time ('last April') requires 'since'."),
    q("They have been rehearsing the stage play ___ three weeks.", "for", "since", "from", "until", "Duration ('three weeks') requires 'for'."),
    q("It is the first time I ___ tasted wood-apple juice.", "have", "had", "am", "was", "'It is the first time' always pairs with Present Perfect 'have'."),
    q("This is the most exciting match our school ___ ever played.", "has", "is", "was", "did", "Superlative + 'ever' takes Present Perfect 'has played'."),
    q("You look tired. ___ you been running around the playground?", "Have", "Are", "Did", "Were", "Present signs of recent continuous effort use 'Have you been + V-ing'."),
    q("Nadeesha's hands are stained with paint; she ___ been painting.", "has", "is", "was", "had", "Visible present evidence of recent activity uses 'has been + V-ing'."),
    q("I promise I ___ never forget your kindness during my illness.", "will", "am", "was", "have", "Promises use 'will + base verb'."),
    q("Perhaps the weather ___ clear up before the prize giving starts.", "will", "is", "did", "has", "Uncertain predictions with 'perhaps' use 'will'."),
    q("I expect our cricket team ___ win the inter-school trophy.", "will", "is", "did", "was", "Personal expectations ('I expect') use 'will'."),
    q("Do you think prices ___ rise next season?", "will", "are", "have", "did", "Future predictions after 'Do you think' take 'will'."),
    q("Hold on; I ___ open the front gate for you right away.", "will", "am", "did", "had", "Instant decision at the moment of speaking takes 'will'."),
    q("We ___ meeting our English teacher at three o'clock tomorrow.", "are", "will", "did", "have", "Fixed personal diary arrangements use Present Continuous 'are meeting'."),
    q("My uncle ___ flying to Singapore on Friday morning.", "is", "will", "did", "has", "Confirmed travel arrangements use Present Continuous 'is flying'."),
    q("Next month, she ___ have worked in this bank for ten years.", "will", "is", "has", "did", "'By/next month... for ten years' takes Future Perfect 'will have V3'."),
    q("By noon tomorrow, the scouts ___ pitched all twelve tents.", "will have", "will be", "are having", "have been", "Action finished before a future point uses 'will have + V3'."),
    q("What ___ you be doing at ten o'clock tomorrow morning?", "will", "are", "have", "did", "Question about an activity in progress at a future time uses 'will'."),
    q("Don't phone between seven and eight; we ___ having dinner.", "will be", "will have", "are been", "were", "Ongoing action during a future window takes 'will be having'."),
    q("Please turn off the fans before you ___ the classroom.", "leave", "will leave", "left", "leaving", "Time clause with 'before' uses Simple Present 'leave'."),
    q("Once the rain ___, we will continue our nature walk.", "stops", "will stop", "stopped", "is stop", "'Once' clause with future result uses Simple Present 'stops'."),
    q("Let us start the meeting as soon as the principal ___.", "arrives", "will arrive", "arrived", "arriving", "'As soon as' takes Simple Present for future events."),
    q("He ___ usually drink coffee, preferring herbal tea instead.", "doesn't", "don't", "isn't", "hasn't", "Negative habit with 'he' requires 'doesn't + base verb'."),
    q("How often ___ the mobile library visit your village?", "does", "do", "is", "has", "Question about frequency with singular subject uses 'does'."),
    q("Neither of those two buses ___ to Matara directly.", "goes", "go", "going", "are going", "'Neither of' takes a singular Simple Present verb 'goes'."),
    q("Why ___ the kettle boiling without any water inside?", "is", "does", "has", "did", "Present Continuous passive/active uses 'is + subject + V-ing'."),
    q("This textbook ___ ten comprehensive grammar units.", "contains", "is containing", "contain", "containing", "Stative 'contain' takes Simple Present singular 'contains'."),
    q("The parcel ___ 2 kilograms according to the postal scale.", "weighs", "is weighing", "weigh", "weighing", "Stative measurement 'weigh' takes Simple Present 'weighs'."),
    q("Right now, the shopkeeper ___ the sack of rice on the scale.", "is weighing", "weighs", "weighed", "has weigh", "Active physical weighing happening now uses 'is weighing'."),
    q("They ___ known each other since primary school days.", "have", "are", "were", "did", "Stative verb 'know' uses Present Perfect Simple 'have known'."),
    q("She ___ owned that blue bicycle for over five years.", "has", "is", "was", "did", "Stative 'own' uses 'has owned' rather than continuous."),
    q("How many essays ___ you written so far this term?", "have", "are", "did", "were", "'So far this term' requires Present Perfect 'have written'."),
    q("Nothing interesting ___ happened in our quiet town all week.", "has", "is", "did", "was", "With 'all week' up to now and 'Nothing', use 'has happened'."),
    q("Someone ___ broken the glass pane on the laboratory window.", "has", "is", "was", "did", "Present evidence of a past action uses 'has broken'."),
    q("Look! The mechanic ___ already repaired the school van.", "has", "is", "was", "had", "'Already' with present visibility takes 'has repaired'."),
    q("We ___ been studying English grammar since eight o'clock.", "have", "are", "were", "did", "'Since 8 o'clock' with 'been studying' takes 'have'."),
    q("He ___ been trying to solve this geometry rider all evening.", "has", "is", "was", "did", "'All evening' up to now with singular 'He' takes 'has'."),
    q("In the future, electric buses ___ become much more common.", "will", "did", "have", "are been", "Future prediction takes 'will + base verb'."),
    q("Watch out! That heavy flowerpot ___ to fall off the ledge.", "is going", "will going", "goes", "was going", "Immediate physical evidence takes 'is going to'."),
    q("The head prefect ___ deliver the vote of thanks at five.", "will", "is", "has", "did", "Formal announcement of future action takes 'will'."),
    q("I ___ probably stay at home and finish my art portfolio.", "will", "am", "was", "have", "'Probably' with future decision takes 'will'."),
    q("Tomorrow afternoon at four, the judges ___ announcing the winners.", "will be", "will have", "are been", "were", "Action occurring at an exact future hour uses 'will be announcing'."),
    q("By next Monday, all students ___ received their new timetables.", "will have", "will be", "are having", "have been", "Completed by a future deadline requires 'will have received'."),
    q("Wait until the traffic light ___ green before crossing.", "turns", "will turn", "turned", "turning", "Future time clause with 'until' takes Simple Present 'turns'.")
  )
}
